"""Algorithm A — Power-residue Frobenius descent.

Computes the residue degree of a prime p in the degree-q subfield K_q of the
f-th cyclotomic field, where f is prime and q divides f-1.  K_q is the fixed
field of the group of q-th powers in (Z/f)^x, so the Frobenius of p is the class
of p modulo that subgroup and the residue degree is the order of that class.
"""

from __future__ import annotations

from math import gcd
from typing import Dict, List, Set, Tuple


def unit_group(f: int) -> List[int]:
    """Representatives of (Z/f)^x."""
    return [u for u in range(1, f) if gcd(u, f) == 1]


def power_subgroup(f: int, q: int) -> Set[int]:
    """The subgroup of q-th powers inside (Z/f)^x, computed in one pass."""
    return {pow(u, q, f) for u in unit_group(f)}


def splits_completely(f: int, q: int, p: int) -> bool:
    """Euler-style criterion, valid when f is prime and q | f-1:
    p is a q-th power mod f  <=>  p^((f-1)/q) = 1 mod f."""
    assert (f - 1) % q == 0, "q must divide f-1"
    return pow(p % f, (f - 1) // q, f) == 1


def residue_degree(f: int, q: int, p: int) -> int:
    """Order of the Frobenius class of p in (Z/f)^x / ((Z/f)^x)^q."""
    powers: Set[int] = power_subgroup(f, q)
    v: int = p % f
    d: int = 1
    while v not in powers:
        v = (v * (p % f)) % f
        d += 1
    return d


def splitting_table(f: int, q: int, limit: int) -> Dict[int, int]:
    """Residue degrees of all primes below `limit` (excluding f)."""
    sieve: List[bool] = [True] * limit
    sieve[0] = sieve[1] = False
    for i in range(2, int(limit**0.5) + 1):
        if sieve[i]:
            for j in range(i * i, limit, i):
                sieve[j] = False
    return {p: residue_degree(f, q, p) for p in range(2, limit) if sieve[p] and p != f}


def split_classes(f: int, q: int) -> Tuple[List[int], float]:
    """The totally split residue classes and their density (always 1/q)."""
    classes = sorted(power_subgroup(f, q))
    return classes, len(classes) / (f - 1)


if __name__ == "__main__":
    classes, density = split_classes(29, 7)
    print("split classes mod 29 :", classes, " density =", density, "= 1/7")
    table = splitting_table(29, 7, 200)
    for p, d in list(table.items())[:12]:
        print(f"  p = {p:4d}   p mod 29 = {p % 29:3d}   residue degree = {d}")
    assert all(
        (d == 1) == (p % 29 in (1, 12, 17, 28)) for p, d in table.items()
    ), "splitting criterion failed"
    assert all(splits_completely(29, 7, p) == (d == 1) for p, d in table.items())
    print("criterion verified for all primes < 200")

"""Algorithm B — Exact evaluation of the three splitting-type channels.

For a degree n the exponent box is B_n = {(a,b) : 0 <= a,b < n} with the uniform
measure.  The residue degree of an exponent is tau(a) = n / gcd(n, a); the hidden
variables are the type pair (unordered pair of residue degrees), the split count
S in {0,1,2}, and the OR bit min(S,1); the observation is the product residue
R = (a+b) mod n.  Each channel is the mutual information I = H - H(.|R).

All tallies are exact integers; the only floating point appears in the final
logarithms.  Cost: O(n^2 log n) time, O(n) memory.
"""

from __future__ import annotations

from math import gcd, log2
from typing import Callable, Dict, Hashable, List, Tuple

Point = Tuple[int, int]


def entropy(counts: List[int]) -> float:
    total: int = sum(counts)
    if total == 0:
        return 0.0
    return -sum((c / total) * log2(c / total) for c in counts if c > 0)


def tally(points: List[Point], key: Callable[[Point], Hashable]) -> List[int]:
    d: Dict[Hashable, int] = {}
    for x in points:
        k = key(x)
        d[k] = d.get(k, 0) + 1
    return list(d.values())


def mutual_information(
    points: List[Point],
    key: Callable[[Point], Hashable],
    side: Callable[[Point], Hashable],
) -> float:
    fibres: Dict[Hashable, List[Point]] = {}
    for x in points:
        fibres.setdefault(side(x), []).append(x)
    cond: float = sum(
        (len(f) / len(points)) * entropy(tally(f, key)) for f in fibres.values()
    )
    return entropy(tally(points, key)) - cond


def channels(n: int) -> Dict[str, float]:
    """Return I_pair(n), I_split(n) and G(n) for the degree n."""
    points: List[Point] = [(a, b) for a in range(n) for b in range(n)]
    tau: Callable[[int], int] = lambda a: n // gcd(n, a)
    type_pair: Callable[[Point], Hashable] = lambda x: (
        min(tau(x[0]), tau(x[1])),
        max(tau(x[0]), tau(x[1])),
    )
    split_count: Callable[[Point], Hashable] = lambda x: (tau(x[0]) == 1) + (tau(x[1]) == 1)
    or_bit: Callable[[Point], Hashable] = lambda x: min(int(split_count(x)), 1)
    residue: Callable[[Point], Hashable] = lambda x: (x[0] + x[1]) % n
    return {
        "I_pair": mutual_information(points, type_pair, residue),
        "I_split": mutual_information(points, split_count, residue),
        "G": mutual_information(points, or_bit, residue),
    }


if __name__ == "__main__":
    print(f"{'n':>3} {'prime?':>7} {'I_pair':>11} {'I_split':>11} {'G':>11} {'gap':>11}")
    for n in range(2, 16):
        c = channels(n)
        prime = n > 1 and all(n % k for k in range(2, int(n**0.5) + 1))
        print(f"{n:3d} {str(prime):>7} {c['I_pair']:11.6f} {c['I_split']:11.6f} "
              f"{c['G']:11.6f} {c['I_pair'] - c['I_split']:11.6f}")
